questions.code:
OPEN emp_cursor;
IF emp_cursor%FOUND THEN
    DBMS_OUTPUT.PUT_LINE('찾음');
END IF;
-- 아직 FETCH를 한 번도 안 한 상태

DECLARE
    CURSOR emp_cursor IS SELECT last_name FROM employees;
    v_name employees.last_name%TYPE;
BEGIN
    LOOP
        FETCH emp_cursor INTO v_name;
        EXIT WHEN emp_cursor%NOTFOUND;
        DBMS_OUTPUT.PUT_LINE(v_name);
    END LOOP;
END;
